import { Routes } from "@angular/router";
import { BookComponent } from "./book/book.component";
import { BookAddComponent } from "./book/book-add/book-add.component";
import { ChapterComponent } from "./chapter/chapter.component";
import { ChapterAddComponent } from "./chapter/chapter-add/chapter-add.component";
import { QuestionComponent } from "./question/question.component";
import { SubjectzComponent } from "./subjectz/subjectz.component";
import { SubjectzAddComponent } from "./subjectz/subjectz-add/subjectz-add.component";
import { RoutezFeatureModule } from "@_core/_route";

export const Routez: Routes = new RoutezFeatureModule(
  ['Syllabus'],
  'feature/syllabus'
)

.feature(
  SubjectzComponent,
  SubjectzAddComponent,
  'subject',
  'Subject'
)

.feature(
  BookComponent,
  BookAddComponent,
  'book',
  'Book'
)

.feature(
  ChapterComponent,
  ChapterAddComponent,
  'chapter',
  'Chapter'
)

.feature(
  QuestionComponent,
  QuestionComponent,
  'question',
  'Question'
)

.build();
